<script setup lang="ts">
import {useLocalDraft} from '@/ui/useLocalDraft';
import {ref,onBeforeUnmount,watch} from 'vue';import {useSessionStore} from '@/session/store';import {captureApiLease,apiRequest,newIdempotencyKey} from '@/api/client';import {CLIENT_RELEASE} from '@/app/release';import {userError} from '@/domain/userError.mjs';import PageHeading from '@/ui/components/PageHeading.vue';import AppIcon from '@/ui/components/AppIcon.vue';
const session=useSessionStore(),description=ref(''),photos=ref<{mime:string;bytes_base64:string;preview:string}[]>([]),picker=ref<HTMLInputElement|null>(null),busy=ref(false),preparing=ref(false),error=ref(''),receipt=ref<number|null>(null);let submission:{key:string;body:any}|undefined,alive=true;
const draft=useLocalDraft<any>('feedback_draft',()=>description.value||photos.value.length||submission?{description:description.value,images:photos.value.map(({mime,bytes_base64})=>({mime,bytes_base64})),submission}:null,value=>{
 if(typeof value.description!=='string'||!Array.isArray(value.images))throw Error('invalid draft');
 description.value=value.description;photos.value=value.images.map((p:any)=>({...p,preview:'data:'+p.mime+';base64,'+p.bytes_base64}));submission=value.submission;
});
async function picture(file:File){if(!file.type.startsWith('image/')||file.type==='image/svg+xml'||file.size>10*1024*1024)throw Error('请选择10MB以内的照片或截图');const bitmap=await createImageBitmap(file);try{if(bitmap.width*bitmap.height>40000000)throw Error('图片尺寸过大');const fit=Math.min(1,1280/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*fit));canvas.height=Math.max(1,Math.round(bitmap.height*fit));const ctx=canvas.getContext('2d');if(!ctx)throw Error('当前设备无法处理图片');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);for(const q of [.85,.7,.55,.4]){const preview=canvas.toDataURL('image/jpeg',q),bytes_base64=preview.split(',')[1];if(bytes_base64.length<=218000)return {mime:'image/jpeg',bytes_base64,preview};}throw Error('图片内容过大，请裁剪后再添加');}finally{bitmap.close();}}
async function selected(e:Event){if(busy.value||preparing.value||submission||!draft.readyToEdit.value)return;const input=e.target as HTMLInputElement,files=Array.from(input.files||[]);input.value='';const lease=captureApiLease();preparing.value=true;error.value='';try{for(const file of files.slice(0,4-photos.value.length)){const photo=await picture(file);if(!alive||!lease.valid())return;photos.value.push(photo);}}catch(e){if(lease.valid())error.value=userError(e,'图片处理失败');}finally{if(alive)preparing.value=false;}}
async function submit(){if(busy.value||preparing.value||!draft.readyToEdit.value||!description.value.trim())return;const lease=captureApiLease();if(!lease.valid())return;busy.value=true;error.value='';const body={description:description.value.trim(),images:photos.value.map(({mime,bytes_base64})=>({mime,bytes_base64})),app_version:CLIENT_RELEASE.versionName};if(!submission)submission={key:newIdempotencyKey('feedback'),body};let attempted=false;try{await draft.flush();attempted=true;const result=await apiRequest<{state:string;feedback_no:number}>('POST','/business/v1/feedback',{body:submission.body,idempotencyKey:submission.key,timeoutMs:30000});if(!alive||!lease.valid())return;if(result.state!=='stored')throw Error('后端未确认保存');receipt.value=result.feedback_no;description.value='';photos.value=[];submission=undefined;await draft.flush();}catch(e){if(!attempted||[400,413,415,422].includes((e as any)?.status)){submission=undefined;await draft.flush().catch(()=>{});}if(alive&&lease.valid())error.value=userError(e,'反馈未提交，请重试');}finally{if(alive)busy.value=false;}}
watch(()=>session.user?.username,()=>{description.value='';photos.value=[];receipt.value=null;submission=undefined;});onBeforeUnmount(()=>{alive=false;});
</script>
<template><div class="feedback-page"><PageHeading title="意见反馈"><RouterLink class="icon-btn" :to="{name:'profile'}" aria-label="返回我的账号"><AppIcon name="back"/></RouterLink></PageHeading><p v-if="draft.restoring.value" role="status" class="field-help">正在恢复草稿…</p><section v-if="receipt" class="feedback-success" role="status"><strong>反馈已提交</strong><p>文字和图片已保存，员工客户端团队可读取处理。</p><button class="btn" @click="receipt=null">继续反馈</button></section><p v-if="draft.error.value" role="alert" class="error-text">{{draft.error.value}}<button type="button" class="btn small" @click="draft.retry().catch(()=>{})">重试保留草稿</button></p><form v-if="!receipt" @submit.prevent="submit"><label for="feedback-description">问题描述</label><textarea id="feedback-description" v-model="description" class="input" maxlength="5000" placeholder="遇到了什么问题？可以补充操作步骤。" :disabled="busy||!!submission||!draft.readyToEdit.value" required></textarea><div class="feedback-photos"><div v-for="(p,i) in photos" :key="p.preview" class="feedback-photo"><img :src="p.preview" :alt="'反馈图片 '+(i+1)"><button type="button" :disabled="busy||!!submission||!draft.readyToEdit.value" :aria-label="'移除反馈图片 '+(i+1)" @click="photos.splice(i,1)"><AppIcon name="close"/></button></div><button v-if="photos.length<4" type="button" class="add-photo" :disabled="busy||preparing||!!submission||!draft.readyToEdit.value" @click="picker?.click()"><AppIcon name="image"/>{{preparing?'处理中…':'添加图片'}}</button></div><input ref="picker" hidden type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif" multiple @change="selected"><small class="field-help">最多添加4张图片。</small><p v-if="error" class="error-text" role="alert">{{error}}</p><button class="btn primary submit-feedback" :disabled="busy||preparing||!draft.readyToEdit.value||!description.trim()">{{busy?'正在提交…':submission?'重试确认':'提交反馈'}}</button></form></div></template>
<style scoped>.feedback-page{max-width:560px;margin:auto}.feedback-page form{display:grid;gap:12px}.feedback-page label{font-size:15px}.feedback-page textarea{width:100%;min-height:150px;resize:vertical;font-size:15px}.feedback-photos{display:flex;gap:10px;flex-wrap:wrap}.feedback-photo{position:relative;width:82px;height:82px}.feedback-photo img{width:100%;height:100%;object-fit:cover;border-radius:6px}.feedback-photo button{position:absolute;right:-6px;top:-6px;width:28px;height:28px;padding:6px;border:0;border-radius:50%;background:var(--ink);color:var(--paper)}.add-photo{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;min-width:82px;width:max-content;height:82px;padding:8px;white-space:nowrap;background:var(--paper);color:var(--muted);border:1px dashed var(--line);border-radius:6px;font-size:12px}.add-photo>.icon{width:24px}.submit-feedback{justify-self:end;min-width:100px}.feedback-success{padding:20px;background:var(--paper);border:1px solid var(--line);border-radius:10px}.feedback-success p{margin:12px 0;font-size:14px;color:var(--muted)}</style>
